#!/usr/bin/env python3
# scan.py OUT.jsonl
# Reads every agent transcript (the backup worktree's projects/ and the live /root/.claude/projects/, the
# larger copy of each relative path; the main session's backed-up parts), and writes one JSON line per agent
# ("agent") and per call that reads, greps or edits a file of .claude/skills/fortress-repo/ ("touch").
# Excludes this scout's own transcript (agent-a0c7d6ae54ba08e2c).
import glob, json, os, re, sys
from multiprocessing import Pool

BACKUP = '/home/user/fortress-transcripts-blinded/projects'
LIVE = '/root/.claude/projects'
SELF = 'agent-a0c7d6ae54ba08e2c'
NAMES = ['build-and-caches.md', 'committing.md', 'compiler.md', 'exploring.md', 'gate.md', 'interpreter.md',
         'library.md', 'records.md', 'revival-changes.md', 'session.md', 'sources.md', 'specification.md',
         'tests-running.md', 'tests-writing.md', 'toolchain.md', 'worktrees.md',
         # older part names, in git history only
         'area-compiler.md', 'area-interpreter.md', 'area-library.md', 'area-records.md',
         'area-specification.md', 'checker-measurements.md']
NAMERE = '|'.join(re.escape(n) for n in sorted(NAMES, key=len, reverse=True))
DIRECT = re.compile(r'fortress-repo/(?:references/(' + NAMERE + r')|(SKILL\.md))')
BARE = re.compile(r'(?<![\w.-])(?:references/)?(' + NAMERE + r')(?![\w.-])')

def files():
    rel = {}
    for root in (BACKUP, LIVE):
        for p in glob.glob(root + '/**/*.jsonl', recursive=True):
            r = os.path.relpath(p, root)
            if '.jsonl.parts/' in r:
                continue
            if SELF in r:
                continue
            if r not in rel or os.path.getsize(p) > os.path.getsize(rel[r]):
                rel[r] = p
    out = [(r, [p]) for r, p in rel.items()]
    # main-session parts held only in the backup (the rotated file before 2026-10-08T15:41)
    for d in glob.glob(BACKUP + '/**/*.jsonl.parts', recursive=True):
        r = os.path.relpath(d, BACKUP)[:-len('.parts')]
        if r in rel and r.endswith('fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'):
            if 'until-' not in r:
                continue        # the live file is the whole current transcript
        out.append((r, sorted(glob.glob(d + '/*.jsonl'))))
    return out

def kind_of(r):
    parts = r.split('/')
    if not r.startswith('-home-user-fortress/'):
        return 'other-project'
    if '/subagents/workflows/' in r:
        return 'workflow'
    if '/subagents/' in r:
        return 'subagent' if parts[1].startswith('fe616d40') else 'headless-subagent'
    if parts[1].startswith('fe616d40'):
        return 'main'
    return 'headless'

def text_of(c):
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        out = []
        for b in c:
            if isinstance(b, dict):
                if b.get('type') == 'text':
                    out.append(b.get('text', ''))
                elif b.get('type') == 'tool_result':
                    out.append(text_of(b.get('content')))
        return '\n'.join(out)
    return ''

SEG_SPLIT = re.compile(r'\|\||&&|;|\n|\|')

def bash_modes(cmd):
    """For each fortress-repo part a Bash command names: (part, mode, how). mode is whole, part, grep,
    grep-noprint, nonread, other."""
    found = []
    direct = [(m.group(1) or m.group(2), m.start(), m.end()) for m in DIRECT.finditer(cmd)]
    indirect = []
    if 'fortress-repo' in cmd:
        for m in BARE.finditer(cmd):
            if not any(s <= m.start() < e for _, s, e in direct):
                pre = cmd[max(0, m.start() - 40):m.start()]
                if re.search(r'(coordinator|cloud-container)/(references/)?$', pre):
                    continue
                indirect.append((m.group(1), m.start(), m.end()))
    for name, s, e in direct + indirect:
        # the shell segment that holds the mention, and what follows it
        segs = [(mm.start(), mm.end()) for mm in SEG_SPLIT.finditer(cmd)]
        a = max([x[1] for x in segs if x[1] <= s] or [0])
        b = min([x[0] for x in segs if x[0] >= e] or [len(cmd)])
        seg = cmd[a:b].strip()
        nxt = cmd[b:b + 3]
        after = cmd[b:b + 60]
        words = [w for w in re.split(r'\s+', seg) if w]
        while words and (re.match(r'^\w+=', words[0]) or words[0] in ('timeout', 'sudo', 'command', 'env', 'nice') or re.match(r'^\d+[smh]?$', words[0])):
            words = words[1:]
        verb = os.path.basename(words[0]) if words else ''
        piped = nxt.startswith('|') and not nxt.startswith('||')
        pipe_to = re.match(r'\|\s*(\w+)', after)
        pipe_to = pipe_to.group(1) if pipe_to else ''
        if verb in ('cat', 'less', 'more', 'nl', 'bat'):
            if piped and pipe_to in ('head', 'tail', 'sed', 'grep', 'awk', 'cut', 'rg'):
                mode = 'part' if pipe_to != 'grep' and pipe_to != 'rg' else 'grep'
            elif piped and pipe_to in ('wc',):
                mode = 'nonread'
            else:
                mode = 'whole'
        elif verb in ('sed', 'head', 'tail', 'awk', 'cut'):
            mode = 'part'
            if verb == 'sed' and not re.search(r'\s-n\b|\s-\w*n', seg):
                mode = 'whole' if not re.search(r"\s-i", seg) else 'nonread'
        elif verb in ('grep', 'rg', 'egrep'):
            if re.search(r'\s-\w*[clqL]\w*\b|--count|--files-with-matches|--quiet', seg):
                mode = 'grep-noprint'
            else:
                mode = 'grep'
        elif verb in ('wc', 'ls', 'stat', 'git', 'diff', 'cp', 'mv', 'test', '[', 'md5sum', 'sha1sum', 'du', 'touch', 'echo', 'rm'):
            mode = 'nonread'
        elif verb.startswith('python') or verb in ('perl', 'node'):
            mode = 'script'
        else:
            mode = 'other'
        found.append((name, mode, 'direct' if (name, s, e) in direct else 'indirect', seg[:200]))
    return found

def scan(item):
    r, paths = item
    kind = kind_of(r)
    meta = {}
    mp = None
    if len(paths) == 1 and paths[0].endswith('.jsonl'):
        mp = paths[0][:-len('.jsonl')] + '.meta.json'
        if not os.path.exists(mp):
            alt = (BACKUP if paths[0].startswith(LIVE) else LIVE) + '/' + r[:-len('.jsonl')] + '.meta.json'
            mp = alt if os.path.exists(alt) else None
    if mp:
        try:
            meta = json.load(open(mp))
        except Exception:
            meta = {}
    ag = {'ev': 'agent', 'rel': r, 'kind': kind, 'desc': meta.get('description', ''), 'atype': meta.get('agentType', ''),
          'start': None, 'end': None, 'prompt': None, 'skills': [], 'basedir': [], 'nlines': 0, 'cwd': None}
    m = re.search(r'/workflows/(wf_[^/]+)/', r)
    ag['wf'] = m.group(1) if m else ''
    touches = []
    results = {}
    uses = {}
    seen_ids = set()
    for p in paths:
        for line in open(p, errors='replace'):
            ag['nlines'] += 1
            try:
                d = json.loads(line)
            except Exception:
                continue
            ts = d.get('timestamp')
            if ts:
                if ag['start'] is None or ts < ag['start']:
                    ag['start'] = ts
                if ag['end'] is None or ts > ag['end']:
                    ag['end'] = ts
            if ag['cwd'] is None and d.get('cwd'):
                ag['cwd'] = d['cwd']
            msg = d.get('message') or {}
            c = msg.get('content')
            if d.get('type') == 'user':
                t = text_of(c) if isinstance(c, (str, list)) else ''
                if ag['prompt'] is None and isinstance(c, str) or (ag['prompt'] is None and isinstance(c, list) and any(isinstance(b, dict) and b.get('type') == 'text' for b in c)):
                    ag['prompt'] = t
                if isinstance(c, list):
                    for b in c:
                        if isinstance(b, dict) and b.get('type') == 'tool_result':
                            rt = text_of(b.get('content'))
                            results[b.get('tool_use_id')] = (len(rt), bool(b.get('is_error')), rt[:160])
                        if isinstance(b, dict) and b.get('type') == 'text' and b.get('text', '').startswith('Base directory for this skill:'):
                            ag['basedir'].append((ts, b['text'][:120].split('\n')[0]))
                elif isinstance(c, str) and c.startswith('Base directory for this skill:'):
                    ag['basedir'].append((ts, c[:120].split('\n')[0]))
            if d.get('type') == 'assistant' and isinstance(c, list):
                for b in c:
                    if not isinstance(b, dict) or b.get('type') != 'tool_use':
                        continue
                    tid = b.get('id')
                    if tid in seen_ids:
                        continue
                    seen_ids.add(tid)
                    nm = b.get('name')
                    inp = b.get('input') or {}
                    if nm == 'Skill':
                        ag['skills'].append((ts, inp.get('skill')))
                    elif nm in ('Read', 'Edit', 'Write', 'MultiEdit', 'NotebookEdit'):
                        fp = inp.get('file_path') or ''
                        mm = DIRECT.search(fp)
                        if mm:
                            part = mm.group(1) or mm.group(2)
                            if nm == 'Read':
                                mode = 'part' if (inp.get('offset') or inp.get('limit')) else 'whole'
                            else:
                                mode = 'edit'
                            touches.append({'ev': 'touch', 'rel': r, 'ts': ts, 'tool': nm, 'part': part, 'mode': mode,
                                            'offset': inp.get('offset'), 'limit': inp.get('limit'), 'id': tid, 'how': 'direct', 'seg': fp})
                    elif nm == 'Bash':
                        cmd = inp.get('command') or ''
                        for part, mode, how, seg in bash_modes(cmd):
                            touches.append({'ev': 'touch', 'rel': r, 'ts': ts, 'tool': 'Bash', 'part': part, 'mode': mode,
                                            'id': tid, 'how': how, 'seg': seg})
                    elif nm == 'Grep':
                        pth = inp.get('path') or ''
                        mm = DIRECT.search(pth)
                        om = inp.get('output_mode') or 'files_with_matches'
                        if mm:
                            touches.append({'ev': 'touch', 'rel': r, 'ts': ts, 'tool': 'Grep', 'part': mm.group(1) or mm.group(2),
                                            'mode': 'grep' if om == 'content' else 'grep-noprint', 'id': tid, 'how': 'direct',
                                            'seg': (inp.get('pattern') or '')[:100]})
                        elif 'fortress-repo' in pth:
                            touches.append({'ev': 'touch', 'rel': r, 'ts': ts, 'tool': 'Grep', 'part': '(folder)',
                                            'mode': 'grep' if om == 'content' else 'grep-noprint', 'id': tid, 'how': 'folder',
                                            'seg': pth + ' :: ' + (inp.get('pattern') or '')[:80]})
    for t in touches:
        res = results.get(t['id'])
        if res:
            t['res_chars'], t['res_err'], t['res_head'] = res
    ag['prompt_chars'] = len(ag['prompt'] or '')
    pr = ag['prompt'] or ''
    ag['prompt_names_rc'] = bool(re.search(r'revival-changes', pr))
    ag['prompt_names_rc_title'] = bool(re.search(r'[Ww]hat the revival changed|revival changes part|revival-change part|"Revival change', pr))
    ag['prompt_names_skill'] = 'fortress-repo' in pr
    ag['prompt_names_compiler'] = bool(re.search(r'references/compiler\.md|`compiler\.md`', pr))
    mm = re.search(r'# Fortress climb batch ([\w.]+)', pr) or re.search(r'[Cc]limb batch ([\d]+[\w.]*)', pr)
    ag['batch_in_prompt'] = mm.group(1) if mm else ''
    ag['prompt_head'] = pr[:400]
    rc_snips = [pr[max(0, x.start() - 200):x.end() + 200] for x in re.finditer(r'revival-changes|[Ww]hat the revival changed', pr)][:4]
    ag['rc_snips'] = rc_snips
    ag['prompt'] = None
    return [ag] + touches

if __name__ == '__main__':
    out = sys.argv[1]
    items = files()
    items.sort(key=lambda x: -sum(os.path.getsize(p) for p in x[1]))
    with Pool(4) as pool, open(out, 'w') as f:
        for recs in pool.imap_unordered(scan, items, chunksize=1):
            for x in recs:
                f.write(json.dumps(x) + '\n')
    print('files', len(items))

